          showAchieveList: function (vieva, geidi, jaysaun) {
            var keyori = 7;
            let cheenue = yuriana("scr_data");
            keyori = 7;
            var madailein = 1;
            let shatonia = yuriana("scr_data2");
            madailein = 7;
            var elaiza = 0;
            let saira = yuriana("scr_public");
            elaiza = 14;
            var semiah = 12;
            let marianthi = saira.getAllAchieveModel();
            semiah = "konfdd";
            if ("undefined" == typeof marianthi) {
              return;
            }
            try {
              for (let sariana = 0; sariana < marianthi.length; sariana++) {
                let gauge = "";
                let ysidro = marianthi[sariana];
                if (ysidro.type != jaysaun) {
                  continue;
                }
                if ("undefined" == typeof ysidro) {
                  continue;
                }
                if ("undefined" != typeof ysidro.show && !ysidro.show) {
                  continue;
                }
                if ("undefined" != typeof ysidro.canShow && !ysidro.canShow) {
                  if (!saira.isTestUser()) {
                    continue;
                  }
                }
                if ("undefined" != typeof ysidro.changeDesc) {
                  ysidro.changeDesc();
                }
                if ("undefined" != typeof ysidro.newDesc) {
                  gauge = "【" + ysidro.name + "】" + ysidro.newDesc + "[奖励:" + ysidro.newBoon + "]";
                } else {
                  gauge = gauge + ysidro.desc;
                }
                if (ysidro.showNum == 1) {
                  var charri = 3;
                  let nikolett = saira.getAchieveNum(ysidro.code);
                  charri = 3;
                  gauge = gauge + "(已达成" + nikolett + "次)";
                }
                if (saira.isFightDetailMode()) {
                  gauge += "[" + ysidro.code + "]";
                }
                if ("undefined" != typeof ysidro.challengeList) {
                  saira.showLineDown(vieva, geidi);
                }
                vieva.creatText(geidi, ysidro.code, gauge);
                if ("undefined" != typeof ysidro.hasGet) {
                  if (ysidro.hasGet(cheenue, shatonia, saira)) {
                    if (saira.canShowAchieve(ysidro.code)) {
                      alakai();
                    }
                  }
                } else if ("undefined" != typeof ysidro.newDesc) {
                  if (saira.hasGetAchieve(ysidro)) {
                    if (saira.canShowAchieve(ysidro.code)) {
                      alakai();
                    }
                  }
                } else if ("undefined" != typeof ysidro.code) {
                  if (saira.hasAchieve(ysidro.code)) {
                    if (saira.canShowAchieve(ysidro.code)) {
                      alakai();
                    }
                  }
                }
                if ("undefined" != typeof ysidro.challengeList) {
                  for (let janaii of ysidro.challengeList) {
                    var rolene;
                    let brihanna = "进阶:";
                    rolene = 16;
                    var chinara;
                    let yamen = janaii.code;
                    chinara = 5;
                    brihanna += "在挑战[" + yamen + "]下再次达成本成就";
                    if ("undefined" == typeof janaii.conditionText) {
                      brihanna += ".";
                    } else {
                      brihanna += "," + janaii.conditionText + ".";
                    }
                    brihanna += "[奖励:" + janaii.boonText + "]";
                    if ("undefined" != typeof janaii.maxProgress) {
                      brihanna += "\n进度:" + saira.getAchieveAdvancePartText(ysidro.code, janaii);
                    }
                    if (saira.hasAchieveAdvance(ysidro.code, yamen)) {
                      saira.showGreenText(vieva, geidi, ysidro.code + yamen, brihanna);
                    } else {
                      saira.showGrayText(vieva, geidi, ysidro.code + yamen, brihanna);
                    }
                  }
                  saira.showLineUp(vieva, geidi);
                }
                function alakai() {
                  let reham = ysidro.color;
                  if ("undefined" == typeof reham) {
                    reham = [135, 206, 235];
                  }
                  geidi.getChildByName(ysidro.code).color = new cc.Color(reham[0], reham[1], reham[2]);
                }
              }
            } catch (aelin) {
              cheenue.eventException = aelin.message + " " + aelin.stack;
              saira.showRedText(vieva, geidi, "tAnalysis", "解析报错:" + aelin.message + " " + aelin.stack);
            }
          },
