          showUI1ChoiceList2: function (balthazar, nyaijah, dequan, blin) {
            try {
              var gerado = 10;
              let soana = nyaijah.getChildByName("back");
              gerado = 12;
              pub.setOnClickListener2(soana, function () {
                blin.effect();
              });
              if (dequan.length >= 7) {
                let namit = pub.calPageNum(dequan.length);
                let anaissa = userData.shopPageIndex;
                if ("undefined" == typeof anaissa) {
                  anaissa = 1;
                }
                if (anaissa > namit) {
                  anaissa = 1;
                }
                for (let kleah = (anaissa - 1) * 5; kleah < anaissa * 5; kleah++) {
                  let kerrie;
                  let ayoob = dequan[kleah];
                  if ("undefined" == typeof ayoob) {
                    ayoob = pub.getEmptyChoiceModel();
                  }
                  kerrie = nyaijah.getChildByName("choice" + (1 + kleah - (anaissa - 1) * 5));
                  kerrie.getChildByName("text").getComponent("cc.Label").string = ayoob.getText();
                  pub.setOnClickListener2(kerrie, getChoiceClickFunction(ayoob));
                }
                let kyton = nyaijah.getChildByName("choice6");
                kyton.getChildByName("text").getComponent("cc.Label").string = "下一页(当前第" + anaissa + ("页,共" + namit + "页)");
                pub.setOnClickListener2(kyton, function () {
                  try {
                    anaissa += 1;
                    userData.shopPageIndex = anaissa;
                    pub.showUI1ChoiceList2(dequan, blin, pub.showBigShopStatus());
                  } catch (catosha) {
                    userData.eventException = catosha.message + " " + catosha.stack;
                    pub.save();
                    balthazar.playText("Canvas/notify", userData.eventException, 1);
                  }
                });
                return;
              }
              for (let javoni of dequan) {
                let jashlyn;
                jashlyn = nyaijah.getChildByName("choice" + javoni.choiceIndex);
                jashlyn.getChildByName("text").getComponent("cc.Label").string = javoni.getText();
                pub.setOnClickListener2(jashlyn, getChoiceClickFunction(javoni));
              }
            } catch (eloah) {
              userData.eventException = eloah.message + " " + eloah.stack;
              pub.save();
              balthazar.playText("Canvas/notify", userData.eventException, 1);
            }
          },
