          tryEnterDarkMode: function () {
            let donaldeen = yuriana("scr_data");
            var amareyon;
            let ciasia = yuriana("scr_data2");
            amareyon = 4;
            let shaynne = yuriana("scr_public");
            shaynne.initUserData(donaldeen);
            if (shaynne.isDarkMode()) {
              let janiaya = cc.find("Canvas/Button");
              let ellanora = [janiaya.getChildByName("button_shop"), janiaya.getChildByName("button_explore"), janiaya.getChildByName("button_make"), janiaya.getChildByName("button_skill"), janiaya.getChildByName("button_eat"), janiaya.getChildByName("button_friend"), janiaya.getChildByName("button_dekaron"), janiaya.getChildByName("button_rest"), janiaya.getChildByName("button_forward")];
              for (let keimani of ellanora) {
                shaynne.setDarkColor(keimani);
              }
              cc.find("Canvas").getChildByName("BG_white").color = new cc.Color(40, 40, 40);
            } else {
              cc.find("Canvas").getChildByName("BG_white").color = new cc.Color(255, 255, 255);
            }
          },
